      "kind": "paragraph",
      "type": "analysis",
      "sectionId": "s5",
      "sectionTitle": "1.4 二维半导体在后摩尔路线中的位置",
      "text": "这也决定了本文的论述重点。如果讨论停留在材料很薄、带隙合适、表面无悬挂键这些描述上，就很容易把材料参数直接等同于芯片性能。更重要的问题是，这些特征到底改善了哪些器件指标，会在哪些工艺环节被削弱，到了反相器、逻辑门和三维集成结构中还能保留多少。",
      "preview": "这也决定了本文的论述重点。如果讨论停留在材料很薄、带隙合适、表面无悬...",
      "citations": [],
