      "text": "基于此，本文按背景需求、材料与器件基础、评价口径、关键进展、工程瓶颈和路线判断的顺序展开。文章主线是：二维半导体的价值首先来自原子级薄沟道，但它能否成为后摩尔技术平台，取决于这种沟道优势是否能被低阻接触、可靠栅介质、互补器件、晶圆制造和小系统验证连续保留下来。",
