      "kind": "paragraph",
      "type": "heading",
      "sectionId": "s9",
      "sectionTitle": "2.3 相对硅基技术的优势与边界",
      "text": "2.3 相对硅基技术的优势与边界",
      "preview": "2.3 相对硅基技术的优势与边界",
