      "kind": "paragraph",
      "type": "evidence",
      "sectionId": "s11",
      "sectionTitle": "2.5 评价口径与报告规范",
      "text": "本文后续把器件结果放到几个具体问题中理解：低接触电阻能否在短接触长度下保持，薄栅介质能否同时维持低漏电和低迟滞，p 型器件能否与 n 型器件在同一供电窗口中配对，晶圆级样品是否给出样本数、良率和参数分布，器件优势能否继续传递到反相器、逻辑模块或小系统。",
      "preview": "本文后续把器件结果放到几个具体问题中理解：低接触电阻能否在短接触长度...",
