      "text": "这些机制可以在后文代表性实验中找到对应证据。接触部分主要对应费米能级钉扎、金属诱导态和接触区相变等问题，无损范德瓦耳斯接触、Y 掺杂 InSe 和 Sb 接触 MoS₂ 等工作分别给出了解决路径[10-13]。介质部分则对应界面偶极、氧空位、栅漏电、阈值调节和范德瓦耳斯间隙带来的低介电串联层问题[14-19]。",
