      "sectionId": "s12",
      "sectionTitle": "3 基础问题与关键进展",
      "text": "极性调控与可靠性问题更多体现在 p 型掺杂、接触稳定、迟滞和阈值漂移上。WSe₂ 表面电荷转移、氯化溶剂掺杂、氧辅助修复和层状金属接触等工作说明，p 型器件的重点已从能否开启，转到低阻接触、低迟滞和统计一致性能否同时成立[8-9,20-22]；迟滞标准化测试和 TCAD 映射工作则把可靠性讨论从曲线现象推进到缺陷动力学分析[23-24]。",
