      "sectionTitle": "3.4 掺杂与极性",
      "text": "后摩尔时代逻辑技术并不只需要优异的单个晶体管，更需要性能匹配的 n 型和 p 型器件来构建互补逻辑。极性调控和稳定掺杂是二维半导体电子技术能否走向 CMOS 的关键环节。二维材料中的传统离子注入并不适用，因为原子级薄膜难以承受高能掺杂过程带来的损伤；与此同时，多数 TMDs 还表现出明显的 n 型倾向，使得 p 型器件的空穴注入和稳定阈值控制尤为困难。",
      "preview": "后摩尔时代逻辑技术并不只需要优异的单个晶体管，更需要性能匹配的 n ...",
