      "type": "synthesis",
      "sectionId": "s16",
      "sectionTitle": "3.4 掺杂与极性",
      "text": "氯仿分子表面掺杂路线与 NO 气相电荷转移掺杂不同，它把 p 型调控讲到了界面机制层面。图 8 给出低温光谱变化、界面吸附构型、势垒演化和态密度重分布，可以看到空穴注入改善并非只是经验调参，而与分子吸附后的能带和界面电荷有关。当前 p 型路线已经不满足于做出 p 型响应，还要解释为什么能做出来、稳定性来自哪里。",
