      "text": "WSe₂ pFET 的近期论文提醒我们，p 型调控不能只看转移曲线是否右移或左移。表面电荷转移掺杂要控制均匀性、作用位置和处理温度，否则很难进入 VLSI 流程[20]。无损 p 型掺杂同样如此：空穴注入变好，如果换来界面破坏，后续互补工艺反而会更难[22]。",
