      "sectionTitle": "3.4 掺杂与极性",
      "text": "国内也已有类似尝试。《物理学报》2025 年报道的一项 WSe₂ 工作，用一步退火和不同金属接触，在同一材料体系上制备了互补晶体管和反相器；器件在 2.5 V 下得到 23 的电压增益和 2.3 V 的总噪声容限[34]。这还不是先进 CMOS 水平，但说明较简单流程也能给出二维互补逻辑雏形。",
