      "sectionTitle": "3.6 晶圆级制备、转移与集成",
      "text": "晶圆级制备要回答的问题更直接：同一种材料和器件结构能不能在大面积样品上反复做出来。这里的制备不只指 CVD、MOCVD 或外延生长，也包括大面积薄膜转移、金属电极集成和后道兼容流程。即便某一种二维器件在实验室中取得了很高性能，如果无法在大面积样品上获得均匀层数、低缺陷密度、稳定极性和可重复的工艺窗口，它仍难以成为现实电子技术。",
      "preview": "晶圆级制备要回答的问题更直接：同一种材料和器件结构能不能在大面积样品...",
