      "sectionId": "s20",
      "sectionTitle": "4.1 先进逻辑",
      "text": "微处理器级演示把设计、工艺和测试放进同一个循环。二维器件此时不再只看单管曲线，版图、互连和测试结果是否能反过来指导工艺改动，也成为评价内容。",
      "preview": "微处理器级演示把设计、工艺和测试放进同一个循环。二维器件此时不再只看...",
