      "text": "这里的图 16 主要把一致性问题落到可观察证据上。超薄介质的电学厚度、漏电、击穿场和器件良率被放在同一组统计结果中，读者可以同时看到工作窗口和失效边界。这样的图比单条漂亮曲线更有价值，因为它直接回答一批器件是否稳定、失效从哪里开始出现。",
