      "sectionTitle": "5.5 与 CMOS 平台的兼容性",
      "text": "上述挑战通过材料缺陷、界面质量、工艺窗口与系统设计要求相互耦合。例如，材料均匀性不足会影响接触可重复性和器件离散性，界面缺陷会削弱可靠性和电路稳定性，缺乏标准化模型则会放大工艺波动在系统设计中的影响。二维半导体不能依赖单一环节突破，而需要材料、器件、工艺与设计方法同步演进。",
