      "kind": "paragraph",
      "type": "evidence",
      "sectionId": "s33",
      "sectionTitle": "6.3 结论",
      "text": "综上，二维半导体在后摩尔时代的意义，不只是提供一种新的沟道材料。更关键的问题是，薄沟道、合适带隙和低温制备带来的优势，能否在接触、介质、极性调控、图形化和晶圆制造中保留下来，并进一步转化为一批器件、一组逻辑单元或一个小系统的稳定表现。",
      "preview": "综上，二维半导体在后摩尔时代的意义，不只是提供一种新的沟道材料。更关...",
